# -*- coding: utf-8 -*-\nimport sys, os\n\n# The batch file content with correct Chinese characters and batch syntax\ncontent = """@echo off\ncd /d "%~dp0"\n"C:\Users\温青\AppData\Local\Python\bin\python.exe" -m pytest %* --basetemp=%TEMP%\pytest_aid\nif errorlevel 1 (\n  echo.\n  echo Tests failed, check output above.\n  pause\n)\n"""\n\noutpath = os.path.join(os.path.dirname(__file__), 'test.bat')\nwith open(outpath, 'w', encoding='utf-8') as f:\n    f.write(content)\nprint('Written to', outpath)\n